from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class EMSERVICELicensedv1HttpClient(HttpClient):
    def __init__(self, base_url, connection_alias):
        super(EMSERVICELicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def plan_activation(self, plan_id, timeout, client_type):
        endpoint = f"/plans/{plan_id}/operations/activations"
        headers = {
            'accept': 'application/json',
            'X-OAM-Client-Type': client_type
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_operation_state_of_activating_plan(self, plan_id, operation_id):
        endpoint = f"/plans/{plan_id}/operations/activations/{operation_id}"
        headers = {
            'accept': 'application/json'
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)

    def get_nms(self, timeout=30):
        endpoint = "/nms"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)
